<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { request } from '../api'
import { useSession } from '../session'
import { useOwnedReads } from '../ownedReads'
import { useProtectedMutation } from '../protectedMutation'
import type { Page } from '../catalog'
import { type Installation,type WorkspacePage,queryString,mergeRows } from '../hardware'
import type { PlcCredential } from '../plc'
import { generateSecret } from '../instances'
import OperationStatus from '../components/OperationStatus.vue'
const session=useSession(),route=useRoute(),mutation=useProtectedMutation(),softwareId=String(route.query.softwareId??'')
const items=ref<PlcCredential[]>([]),next=ref<string|null>(null),rows=ref<Installation[]>([]),rowNext=ref<string|null>(null),failure=ref('')
const selection=ref(new Map<string,Installation>()),search=ref(''),applied=ref(''),name=ref(''),expires=ref(''),secret=ref(''),reason=ref(''),issued=ref<PlcCredential|null>(null)
const draft=ref<{epoch:number;revoke:PlcCredential|null}|null>(null),dialog=ref<HTMLDialogElement|null>(null);let focus:HTMLElement|null=null
const reads=useOwnedReads(()=>{items.value=[];next.value=null;rows.value=[];rowNext.value=null;selection.value.clear();secret.value='';issued.value=null})
const valid=computed(()=>draft.value?.epoch===reads.epoch.value&&session.can('plc.uploadCredential.manage',softwareId))
const get=<T,>(p:string,s:AbortSignal)=>request<T>(p,'GET',undefined,undefined,undefined,{signal:s})
const fail=(e:unknown)=>{failure.value=e instanceof Error?e.message:'读取失败'}
async function load(cursor?:string|null){await reads.run('credentials',!cursor,s=>get<Page<PlcCredential>>(`/api/v1/manage/software/${softwareId}/plc-upload-credentials?${queryString({},cursor)}`,s),p=>{items.value=cursor?mergeRows(items.value,p.items,x=>x.id):p.items;next.value=p.nextCursor},fail)}
async function candidates(cursor?:string|null){const name=cursor?applied.value:search.value.trim();await reads.run('controllers',!cursor,s=>get<WorkspacePage<Installation>>('/api/v1/manage/workspace/installations?'+queryString({softwareId,name},cursor),s),p=>{rows.value=cursor?mergeRows(rows.value,p.items,x=>x.rowId):p.items;rowNext.value=p.nextCursor;applied.value=name},fail)}
function select(row:Installation,event:Event){if((event.target as HTMLInputElement).checked)selection.value.set(row.position!.id,JSON.parse(JSON.stringify(row)));else selection.value.delete(row.position!.id)}
async function open(revoke:PlcCredential|null=null){if(mutation.blocked.value)return;focus=document.activeElement as HTMLElement;draft.value={epoch:reads.epoch.value,revoke:revoke?JSON.parse(JSON.stringify(revoke)):null};name.value='';expires.value='';reason.value='';secret.value=revoke?'':generateSecret();issued.value=null;selection.value.clear();await nextTick();dialog.value?.showModal();if(!revoke)await candidates()}
function close(){if(mutation.blocked.value)return;dialog.value?.close();draft.value=null;secret.value='';issued.value=null;reads.invalidate('controllers');focus?.focus()}
async function save(){const d=draft.value;if(!d||!mutation.uncertain.value&&(!valid.value||!d.revoke&&(!selection.value.size||!Number.isFinite(Date.parse(expires.value)))))return;const path=d.revoke?`/api/v1/manage/plc-upload-credentials/${d.revoke.id}/revoke`:`/api/v1/manage/software/${softwareId}/plc-upload-credentials`;const body=d.revoke?{expectedRevision:d.revoke.revision,reason:reason.value}:{name:name.value,scope:[...selection.value.values()].map(r=>({bindingId:r.position!.id,bindingRevision:r.position!.revision})),expiresAt:expires.value?new Date(expires.value).toISOString():null,secretMaterial:secret.value};const result=await mutation.perform<PlcCredential>(path,'POST',body,session.current!.csrfToken);if(result&&mutation.completed.value){if(!d.revoke&&valid.value)issued.value=result;else close();await load()}}
onMounted(()=>load());onUnmounted(()=>{secret.value=''})
</script>
<template>
<section class="panel plc-access"><div class="page-heading"><div><h2>PLC 上传接入</h2><p class="muted">凭据仅能向当前程序库、所选控制器范围上传归档。它不能发布或登记现场使用。</p></div><button v-if="session.can('plc.uploadCredential.manage',softwareId)" class="primary" :disabled="mutation.blocked.value" @click="open()">签发上传凭据</button></div><p v-if="failure" class="error">{{ failure }}</p><div class="table-scroll" tabindex="0" role="region" aria-label="PLC 上传凭据"><table><thead><tr><th>名称</th><th>控制器范围</th><th>到期时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in items" :key="c.id"><td>{{ c.name }}</td><td>{{ c.scope.length }} 个固定关联</td><td>{{ new Date(c.expiresAt).toLocaleString() }}</td><td>{{ c.revokedAt?'已吊销':Date.parse(c.expiresAt)<=Date.now()?'已到期':'有效' }}</td><td><button v-if="!c.revokedAt" :disabled="mutation.blocked.value" @click="open(c)">吊销</button></td></tr></tbody></table><p v-if="!items.length" class="empty">暂无上传凭据。</p></div><button v-if="next" :disabled="reads.busy.value" @click="load(next)">更多凭据</button>
<dialog ref="dialog" @cancel.prevent="close" aria-labelledby="plc-credential-title"><template v-if="draft"><h2 id="plc-credential-title">{{ draft.revoke?'吊销 '+draft.revoke.name:'签发固定范围上传凭据' }}</h2><form @submit.prevent="save"><fieldset :disabled="mutation.blocked.value||!valid||!!issued"><template v-if="!draft.revoke"><label>用途名称<input v-model="name" required maxlength="128" /></label><label>到期时间<input v-model="expires" type="datetime-local" required /></label><p class="muted">期限受部署配置上限约束；关联被撤销或重建后，旧凭据范围不会自动恢复。</p><div class="selector-search"><input v-model="search" placeholder="搜索控制器或设备" /><button type="button" @click="candidates()">查询</button></div><label v-for="r in rows.filter(r=>r.position)" :key="r.rowId" class="check"><input type="checkbox" :checked="selection.has(r.position!.id)" @change="select(r,$event)" />{{ r.device.name }} / {{ r.hardware?.name }}</label><button v-if="rowNext" type="button" @click="candidates(rowNext)">更多控制器</button><p>已选 {{ selection.size }} 个关联</p></template><label v-else>吊销原因<textarea v-model="reason" required maxlength="256" /></label></fieldset><p v-if="!valid" class="error">人员或权限已变化，原草稿不能继续。</p><div v-if="issued&&secret" class="grant-material"><h3>请安全保存，此秘密只在当前表单显示</h3><label>凭据标识<input readonly :value="issued.id" /></label><label>秘密<input readonly :value="secret" autocomplete="off" /></label><p class="muted">API /api/v1/plc-upload；按厂家接入文档组装 Bearer。关闭后清除秘密；服务端不保存可取回的秘密。</p></div><p v-if="mutation.error.value" class="error">{{ mutation.error.value }}</p><OperationStatus :mutation="mutation" /><div class="dialog-actions"><button type="button" :disabled="mutation.blocked.value" @click="close">{{ issued?'关闭并清除秘密':'取消' }}</button><button v-if="!issued" class="primary" :disabled="mutation.busy.value||!valid&&!mutation.uncertain.value">{{ mutation.uncertain.value?'核实原操作':'确认' }}</button></div></form></template></dialog></section>
</template>
<style scoped>.plc-access{padding:1.5rem}fieldset{border:0;padding:0;display:grid;gap:1rem}dialog{max-width:42rem;width:calc(100% - 3rem)}.grant-material{padding:1rem;background:#f0f6ff;overflow-wrap:anywhere}</style>
